import assert from'node:assert/strict';import{mkdirSync,readFileSync,writeFileSync}from'node:fs';import{chromium,webkit}from'playwright';
const data=JSON.parse(readFileSync('outputs/goal-audit-20261101/inventory.json')),base=process.env.KLINK_TEST_URL||'http://127.0.0.1:18996',out=process.env.KLINK_AUDIT_OUTPUT||'outputs/goal-audit-20261101/local';mkdirSync(out,{recursive:true});const checks=[],errors=[];
for(const[engine,type]of Object.entries({chromium,webkit})){const browser=await type.launch();try{const context=await browser.newContext({viewport:engine==='chromium'?{width:390,height:844}:{width:320,height:568},hasTouch:true});const wanted=engine==='chromium'?data.cases:data.activities.filter(a=>a.first).map(a=>a.first);for(const c of wanted){const p=await context.newPage();p.setDefaultTimeout(6000);const entry={engine,activity:c.activity,key:c.key,id:c.exercise.exerciseId,mode:c.exercise.mode,goal:c.goal.id};try{await p.addInitScript(c=>{localStorage.setItem(`klink.group.v1:chapter:${c.activity}:${c.collection}:${c.activity}`,JSON.stringify({version:1,done:false,exerciseId:c.exercise.exerciseId}));if(c.activity==='learning-review')localStorage.setItem('klink.learning-review.v1',JSON.stringify({[c.exercise.exerciseId]:{due:0,last:0,streak:0}}));localStorage.setItem('klink.audit.retention','kept');},c);await p.goto(base+c.route);const root=p.locator('[data-exercise-id]');if(['worksheet','worksheet-heard'].includes(c.activity)){await p.locator('[data-worksheet-exercise]').first().waitFor();entry.layout='per-item-tools';const item=p.locator('[data-worksheet-exercise]').first();entry.infoCount=await item.getByRole('button',{name:'Over deze oefening',exact:true}).count();entry.infoInHeader=await item.locator('header').getByRole('button',{name:'Over deze oefening',exact:true}).count()===1;await item.getByRole('button',{name:'Over deze oefening',exact:true}).press('Enter');}else{await root.waitFor();assert.equal(await root.getAttribute('data-exercise-id'),c.exercise.exerciseId,'seeded position');entry.layout='single';const header=p.locator('.cp-exercise-record-head');entry.infoCount=await p.getByRole('button',{name:'Over deze oefening',exact:true}).count();entry.infoInHeader=await header.getByRole('button',{name:'Over deze oefening',exact:true}).count()===1;if(!entry.infoCount){entry.protected=Boolean(c.exercise.contentTask?.teacherReference||c.exercise.access!=='self-practice');assert(entry.protected,'Only deliberately protected instructions may start hidden');const begin=p.getByRole('button',{name:'Begin samen',exact:true});if(await begin.count())await begin.tap();for(let attempt=0;attempt<30;attempt++){const own=p.getByRole('button',{name:'Ik heb eerst zelf geantwoord',exact:true});if(!await own.count())break;const field=p.locator('.cp-content-task textarea');if(await field.count())await field.fill('Mijn eigen antwoord.');await own.tap();}entry.infoCount=await p.getByRole('button',{name:'Over deze oefening',exact:true}).count();entry.infoInHeader=await header.getByRole('button',{name:'Over deze oefening',exact:true}).count()===1;entry.ownResponsePreserved=true;}await header.getByRole('button',{name:'Over deze oefening',exact:true}).press('Enter');}
assert(entry.infoInHeader);assert.equal(entry.infoCount,1);const d=p.getByRole('dialog');await d.waitFor();await p.waitForTimeout(150);entry.actualGoal=await d.locator('[data-learning-goal]').getAttribute('data-learning-goal');assert.equal(entry.actualGoal,c.goal.id);entry.labels=await d.locator('.cp-learning-goal-labels span').allTextContents();assert.deepEqual(entry.labels,c.goal.displayLabels);entry.goalFits=await d.evaluate(e=>{const r=e.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight;});assert(entry.goalFits);await p.keyboard.press('ArrowRight');assert(await d.isVisible());await p.keyboard.press('Escape');await d.waitFor({state:'hidden'});entry.keyboardContained=true;entry.storagePreserved=await p.evaluate(()=>localStorage.getItem('klink.audit.retention')==='kept');assert(entry.storagePreserved);checks.push(entry);}catch(e){entry.error=String(e.message);errors.push(entry);}finally{await p.close();writeFileSync(out+'/checks.json',JSON.stringify({base,checks,errors},null,2)+'\n');}}await context.close();}finally{await browser.close();}}
console.log('Audit',checks.length,'cases,',errors.length,'errors,',checks.filter(c=>!c.infoInHeader).length,'header differences');if(errors.length)process.exitCode=1;

assert.equal(checks.length,data.cases.length+data.activities.filter(a=>a.first).length);assert.deepEqual(errors,[]);
